    private static final int BG=Color.rgb(243,244,246), NAVY=Color.rgb(17,24,39), GREEN=Color.rgb(22,132,67), RED=Color.rgb(190,35,35), BLUE=Color.rgb(37,84,204), BORDER=Color.rgb(210,214,220);
