    static class GoogleSync {
        private static final String WEB_CLIENT_ID="684260435515-ijo5egmulann3o6hl2u79400cv09h1sl.apps.googleusercontent.com";
        private static final String API_KEY="AIzaSyBne-T-nOC6oLYc96jhd-tpYQxja8lNhG4";
        private static final String APP_ID="1:684260435515:web:b67441528fde0229fc5e1e";
        private static final String PROJECT_ID="symmetric-curve-475011-h8";
        private static final String BUCKET="symmetric-curve-475011-h8.firebasestorage.app";
        private static FirebaseAuth auth; private static FirebaseFirestore db; private static boolean initialized=false;
        static void init(Activity a){try{if(FirebaseApp.getApps(a).isEmpty()){FirebaseOptions o=new FirebaseOptions.Builder().setApiKey(API_KEY).setApplicationId(APP_ID).setProjectId(PROJECT_ID).setStorageBucket(BUCKET).build();FirebaseApp.initializeApp(a,o);}auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();if(!initialized){initialized=true;auth.addAuthStateListener(x->{if(x.getCurrentUser()!=null)pull(a);});}}catch(Exception e){}}
        static boolean connected(){return auth!=null&&auth.getCurrentUser()!=null;}
        static void signIn(Activity a){init(a);if(auth==null){show(a,"Não foi possível preparar o Google.");return;}try{CredentialManager cm=CredentialManager.create(a);GetGoogleIdOption opt=new GetGoogleIdOption.Builder().setFilterByAuthorizedAccounts(false).setAutoSelectEnabled(false).setServerClientId(WEB_CLIENT_ID).build();GetCredentialRequest req=new GetCredentialRequest.Builder().addCredentialOption(opt).build();cm.getCredentialAsync(a,req,new CancellationSignal(),a.getMainExecutor(),new CredentialManagerCallback<GetCredentialResponse,GetCredentialException>(){@Override public void onResult(@NonNull GetCredentialResponse r){try{Credential c=r.getCredential();if(!(c instanceof CustomCredential)||!GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL.equals(c.getType())){show(a,"Nenhuma conta Google foi selecionada.");return;}GoogleIdTokenCredential g=GoogleIdTokenCredential.createFrom(((CustomCredential)c).getData());AuthCredential fc=GoogleAuthProvider.getCredential(g.getIdToken(),null);auth.signInWithCredential(fc).addOnSuccessListener(v->{a.runOnUiThread(()->{Toast.makeText(a,"Google conectado. Sincronização ativada.",Toast.LENGTH_LONG).show();a.recreate();});}).addOnFailureListener(e->show(a,"Google não autorizou a conexão. Tente outra conta."));}catch(Exception e){show(a,"Não foi possível concluir a conexão Google." );}}@Override public void onError(@NonNull GetCredentialException e){show(a,"Não foi possível abrir as contas Google. Verifique se o Google Play Services está atualizado.");}});}catch(Exception e){show(a,"Erro ao abrir a conexão Google. O aplicativo continua funcionando normalmente.");}}
        private static void show(Activity a,String s){a.runOnUiThread(()->Toast.makeText(a,s,Toast.LENGTH_LONG).show());}
        static void push(Activity a,JSONArray state){if(!connected()||db==null)return;FirebaseUser u=auth.getCurrentUser();if(u==null)return;HashMap<String,Object> p=new HashMap<>();p.put("state",state.toString());p.put("email",u.getEmail());p.put("updatedAt",System.currentTimeMillis());db.collection("users").document(u.getUid()).set(p,SetOptions.merge());}
        static void pull(Activity a){if(!connected()||db==null)return;FirebaseUser u=auth.getCurrentUser();if(u==null)return;db.collection("users").document(u.getUid()).get().addOnSuccessListener(s->{Object raw=s.get("state");if(!(raw instanceof String))return;try{JSONArray ar=new JSONArray((String)raw);MainActivity m=(MainActivity)a;m.data.clear();for(int i=0;i<ar.length();i++){JSONObject o=ar.getJSONObject(i);Tx x=new Tx();x.id=o.optString("id",UUID.randomUUID().toString());x.type=o.optString("type","out");x.amount=o.optDouble("amount",0);x.category=o.optString("category","Mercado");x.date=o.optString("date",m.today());x.desc=o.optString("desc","");m.data.add(x);}m.persist();m.runOnUiThread(m::refresh);}catch(Exception ignored){}});}
    }
